#include "tools.hpp"
#include <iostream>

using namespace hub;
int wmain(int argc,wchar_t**argv){try{std::error_code ignored;fs::remove(root()/L"evidence/agent-driver-error.txt",ignored);fs::remove(root()/L"evidence/app-agent-integration.json",ignored);bool manual=argc==2&&std::wstring_view(argv[1])==L"--manual-encrypted";if(argc>1&&!manual)throw std::runtime_error("Unknown agent test mode.");
 if(FindWindowW(L"Pageant",L"Pageant"))throw std::runtime_error("An existing Pageant is present; test did not modify it.");WIN32_FIND_DATAW info{};auto search=FindFirstFileW(L"\\\\.\\pipe\\pageant.*",&info);if(search!=INVALID_HANDLE_VALUE){FindClose(search);throw std::runtime_error("An existing Pageant pipe is present; test did not modify any agent.");}
 Components components(root()/L"components");Handle job(CreateJobObjectW(nullptr,nullptr));check(static_cast<bool>(job),"Create isolated agent test lifetime");JOBOBJECT_EXTENDED_LIMIT_INFORMATION limits{};limits.BasicLimitInformation.LimitFlags=JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;check(SetInformationJobObject(job.get(),JobObjectExtendedLimitInformation,&limits,sizeof(limits))!=FALSE,"Set agent test cleanup");
 auto launch=[&](const fs::path&exe,const std::vector<std::wstring>&arguments){auto process=start_process(exe,arguments,CREATE_SUSPENDED);if(!AssignProcessToJobObject(job.get(),process.process.get())){TerminateProcess(process.process.get(),1);throw std::runtime_error("Cannot own test process.");}check(ResumeThread(process.thread.get())!=static_cast<DWORD>(-1),"Start owned agent test process");return process;};
 auto agent=launch(components.require("pageant"),{});HWND receiver=nullptr;const auto deadline=GetTickCount64()+5000;while(GetTickCount64()<deadline&&agent.running()){receiver=FindWindowW(L"Pageant",L"Pageant");if(receiver)break;Sleep(20);}DWORD receiver_pid=0;if(receiver)GetWindowThreadProcessId(receiver,&receiver_pid);check(receiver_pid==agent.pid,"Own the native Pageant IPC receiver before adding a fixture");
 auto file=root()/L"tests/ssh-fixture"/(manual?L"agent-encrypted-test.ppk":L"agent-test.ppk");auto load=launch(components.require("pageant"),pageant_key_arguments(file));check(WaitForSingleObject(load.process.get(),manual?120000:5000)==WAIT_OBJECT_0&&load.exit_code()==0,"Native Pageant loaded disposable PPK");
 auto app=launch(root()/L"bin/PuTTYHub.exe",{L"--integration-agent-test"});if(WaitForSingleObject(app.process.get(),30000)!=WAIT_OBJECT_0)throw std::runtime_error("Agent application test timed out.");check(app.exit_code()==0,"Agent authentication through actual Hub and WinSCP");if(manual){auto report=Json::parse(read_bytes(root()/L"evidence/app-agent-integration.json"));report["scope"]="Encrypted disposable PPK unlocked manually in native Pageant, then agent-only Hub and WinSCP authenticated";write_text(root()/L"evidence/app-agent-encrypted-integration.json",report.dump(2));}std::cout<<"Pageant cross-tool public-key authentication passed.\n";return 0;
 }catch(const std::exception&e){write_text(root()/L"evidence/agent-driver-error.txt",e.what());std::cerr<<e.what()<<"\n";return 1;}}
